{"profile": {"name": "Jay", "age": 17, "communication_style": "short phrases"}, "activity": "Choose to hear a poem, look at a comic, or sit quietly during a reading group.", "facts": ["Jay", "has", "not", "stated", "a", "preference.", "A", "friend", "enjoys", "comics,", "but", "that", "is", "not", "Jay's", "preference."], "shared_context": "Held-out fictional case. Full communication access remains available. Cards are optional supplements, not claims about current intent.", "word_limit": 8}
